#include <vector>

class Solution {
public:
    int countNonAdjacentSubsets(std::vector<int>& parent, std::vector<int>& nums, int k) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        std::vector<std::vector<int>> children(n);
        for (int i = 1; i < n; ++i) children[parent[i]].push_back(i);

        auto dfs = [&](auto& self, int u) -> std::pair<std::vector<int>, std::vector<int>> {
            std::vector<int> dp0(k, 0), dp1(k, 0);
            dp0[0] = 1;
            dp1[nums[u] % k] = 1;
            for (int v : children[u]) {
                auto [c0, c1] = self(self, v);
                std::vector<int> cComb(k, 0);
                for (int r = 0; r < k; ++r) cComb[r] = (c0[r] + c1[r]) % MOD;
                std::vector<int> nextDp0(k, 0), nextDp1(k, 0);
                for (int r1 = 0; r1 < k; ++r1) {
                    if (!dp0[r1]) continue;
                    for (int r2 = 0; r2 < k; ++r2) {
                        if (!cComb[r2]) continue;
                        int nr = (r1 + r2) % k;
                        nextDp0[nr] = (nextDp0[nr] + 1LL * dp0[r1] * cComb[r2]) % MOD;
                    }
                }
                for (int r1 = 0; r1 < k; ++r1) {
                    if (!dp1[r1]) continue;
                    for (int r2 = 0; r2 < k; ++r2) {
                        if (!c0[r2]) continue;
                        int nr = (r1 + r2) % k;
                        nextDp1[nr] = (nextDp1[nr] + 1LL * dp1[r1] * c0[r2]) % MOD;
                    }
                }
                dp0 = std::move(nextDp0);
                dp1 = std::move(nextDp1);
            }
            return {dp0, dp1};
        };

        auto [rootDp0, rootDp1] = dfs(dfs, 0);
        int ans = (rootDp0[0] + rootDp1[0] - 1 + MOD) % MOD;
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countNonAdjacentSubsets(int[] parent, int[] nums, int k) {
        int MOD = 1_000_000_007;
        int n = nums.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) children.get(parent[i]).add(i);

        long[][] res = dfs(0, children, nums, k, MOD);
        long ans = (res[0][0] + res[1][0] - 1 + MOD) % MOD;
        return (int)ans;
    }

    private long[][] dfs(int u, List<List<Integer>> children, int[] nums, int k, int MOD) {
        long[] dp0 = new long[k];
        dp0[0] = 1;
        long[] dp1 = new long[k];
        dp1[nums[u] % k] = 1;
        for (int v : children.get(u)) {
            long[][] childRes = dfs(v, children, nums, k, MOD);
            long[] c0 = childRes[0];
            long[] c1 = childRes[1];
            long[] cComb = new long[k];
            for (int r = 0; r < k; r++) cComb[r] = (c0[r] + c1[r]) % MOD;
            long[] nextDp0 = new long[k];
            long[] nextDp1 = new long[k];
            for (int r1 = 0; r1 < k; r1++) {
                if (dp0[r1] == 0) continue;
                for (int r2 = 0; r2 < k; r2++) {
                    if (cComb[r2] == 0) continue;
                    int nr = (r1 + r2) % k;
                    nextDp0[nr] = (nextDp0[nr] + dp0[r1] * cComb[r2]) % MOD;
                }
            }
            for (int r1 = 0; r1 < k; r1++) {
                if (dp1[r1] == 0) continue;
                for (int r2 = 0; r2 < k; r2++) {
                    if (c0[r2] == 0) continue;
                    int nr = (r1 + r2) % k;
                    nextDp1[nr] = (nextDp1[nr] + dp1[r1] * c0[r2]) % MOD;
                }
            }
            dp0 = nextDp0;
            dp1 = nextDp1;
        }
        return new long[][]{dp0, dp1};
    }
}

